CREATE TYPE public.app_role AS ENUM ('admin');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL DEFAULT 'admin', UNIQUE(user_id, role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_role_read ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated, service_role;
CREATE TABLE public.site_content (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kind text NOT NULL CHECK(kind IN ('product','article','category','retailer','settings','event')), slug text NOT NULL, title text NOT NULL, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','archived')), data jsonb NOT NULL DEFAULT '{}', published_at timestamptz, updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(kind,slug));
GRANT SELECT ON public.site_content TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.site_content TO authenticated; GRANT ALL ON public.site_content TO service_role;
ALTER TABLE public.site_content ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_published ON public.site_content FOR SELECT TO anon,authenticated USING (status='published' AND (published_at IS NULL OR published_at<=now()));
CREATE POLICY owner_content ON public.site_content FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.contact_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, email text NOT NULL, message text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,DELETE ON public.contact_messages TO authenticated; GRANT ALL ON public.contact_messages TO service_role;
ALTER TABLE public.contact_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY owner_messages ON public.contact_messages FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'admin'));
CREATE TABLE public.audit_log (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid NOT NULL, action text NOT NULL, content_id uuid, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.audit_log TO authenticated; GRANT ALL ON public.audit_log TO service_role;
ALTER TABLE public.audit_log ENABLE ROW LEVEL SECURITY;
CREATE POLICY owner_audit ON public.audit_log FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.audit_content_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.audit_log(actor_id,action,content_id) VALUES(auth.uid(),TG_OP,COALESCE(NEW.id,OLD.id)); RETURN COALESCE(NEW,OLD); END $$;
CREATE TRIGGER content_audit AFTER INSERT OR UPDATE OR DELETE ON public.site_content FOR EACH ROW EXECUTE FUNCTION public.audit_content_change();
CREATE TABLE public.request_limits (key text PRIMARY KEY, count integer NOT NULL DEFAULT 0, started_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.request_limits TO service_role;
ALTER TABLE public.request_limits ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.take_request_slot(p_key text,p_limit integer,p_seconds integer) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer; BEGIN INSERT INTO public.request_limits(key,count) VALUES(p_key,1) ON CONFLICT(key) DO UPDATE SET count=CASE WHEN request_limits.started_at < now()-make_interval(secs=>p_seconds) THEN 1 ELSE request_limits.count+1 END, started_at=CASE WHEN request_limits.started_at < now()-make_interval(secs=>p_seconds) THEN now() ELSE request_limits.started_at END RETURNING count INTO n; RETURN n<=p_limit; END $$;
REVOKE ALL ON FUNCTION public.take_request_slot(text,integer,integer) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.take_request_slot(text,integer,integer) TO service_role;